xql_query:
// ============================================================
// Rule: WIN_Flag Password Never Expire
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Flag Password Never Expire.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1098 - Account Manipulation

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: capturar variações de caixa na mensagem do evento (ex.: "Password Never Expires")
config case_sensitive = false

// Fonte de dados: telemetria do agente (inclui Windows Event Log)
| dataset = xdr_data

// Filtro: eventos do Windows Event Log (opcional, mas recomendado para reduzir ruído)
// | filter event_type = ENUM.EVENT_LOG

// Evento 4738 = "A user account was changed" (AD/Windows Security)
// Usado para identificar alterações em atributos de contas, incluindo flags de senha.
| filter action_evtlog_event_id = 4738

// Filtro: busca indícios de configuração de senha para nunca expirar
// - "DONT_EXPIRE_PASSWORD" é um flag típico em logs/strings do AD
// - "Password Never Expire" cobre variações de texto registradas na mensagem
| filter (
    action_evtlog_message contains "DONT_EXPIRE_PASSWORD" or
    action_evtlog_message contains "Password Never Expire"
)

// Saída: campos mínimos para auditoria rápida
| fields
    _time,                   // Timestamp do evento
    action_evtlog_event_id,  // Event ID (4738)
    action_evtlog_message    // Mensagem completa (inclui detalhes da alteração)
